-- One-time demo cleanup explicitly authorized by owner. Not a schema migration.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
LOCK TABLE public."prescription_items",public."payments",public."lab_tests",public."appointments",public."referrals",public."prescriptions",public."patients" IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE cleanup_auth_guard ON COMMIT DROP AS SELECT count(*) AS n FROM auth.users;
